### Result
{"verdict":"PASS","checks":["Search DEV","Search Quarry","Search contact6@","Combined filters","Filtered empty","Unassigned"]}
### Ran Playwright code
```js
await (async(page)=>{
await page.setViewportSize({width:1440,height:900}); const checks=[];
for(const q of ['DEV','Quarry','contact6@']){
await page.getByRole('searchbox').fill(q);await page.getByText('1 of 6 contacts').waitFor();checks.push('Search '+q);}
await page.getByRole('button',{name:'Clear filters'}).click();
await page.getByLabel('Owner',{exact:true}).selectOption({label:'Mara Okafor'});await page.getByLabel('Status',{exact:true}).selectOption('Active');
await page.getByText('3 of 6 contacts').waitFor();checks.push('Combined filters');
await page.getByRole('searchbox').fill('no-such-fictional-contact');await page.getByText('No contacts match').waitFor();checks.push('Filtered empty');
await page.getByRole('button',{name:'Clear filters'}).first().click();
await page.getByLabel('Owner',{exact:true}).selectOption('none');await page.getByText('1 of 6 contacts').waitFor();checks.push('Unassigned');
await page.getByRole('button',{name:'Clear filters'}).click();
return {verdict:'PASS',checks};
})(page);
```
